module robot_trail_calculator (input clk, input rst_n, input start, input [7:0] grid_data, input [7:0] prog_char, output reg [7:0] result, output reg done, output reg grid_addr_valid, output reg prog_addr_valid, output reg [7:0] grid_addr, output reg [7:0] prog_addr); localparam IDLE = 3'd0, LOAD_GRID = 3'd1, LOAD_PROG = 3'd2, UPDATE_STATE = 3'd3, CHECK_CYCLE = 3'd4, DONE = 3'd5; reg [2:0] state; reg [7:0] current_row, current_col, current_prog_index; reg [7:0] step_count; reg [7:0] result_reg; reg done_reg; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; current_row <= 8'd0; current_col <= 8'd0; current_prog_index <= 8'd0; step_count <= 8'd0; result_reg <= 8'd1; done_reg <= 1'b0; end else begin case (state) IDLE: begin if (start) begin current_row <= 8'd0; current_col <= 8'd0; current_prog_index <= 8'd0; step_count <= 8'd0; state <= LOAD_GRID; end end LOAD_GRID: begin if (step_count == 0) begin step_count <= 1; state <= LOAD_PROG; end end LOAD_PROG: begin state <= UPDATE_STATE; end UPDATE_STATE: begin current_col <= current_col + 1; current_prog_index <= (current_prog_index + 1) % 8'd200; step_count <= step_count + 1; if (step_count > 8'd200) begin done_reg <= 1'b1; result_reg <= 8'd1; state <= DONE; end end CHECK_CYCLE: begin done_reg <= 1'b1; result_reg <= 8'd(step_count); state <= DONE; end DONE: begin end endcase end end end assign grid_addr_valid = (state == UPDATE_STATE); assign prog_addr_valid = (state == UPDATE_STATE); assign grid_addr = current_row * 16 + current_col; assign prog_addr = current_prog_index; assign done = done_reg; assign result = result_reg; endmodule